// Verus program: split an array into two parts with precise guarantees.
#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn array_split(a: Vec<i32>) -> (b: Vec<i32>, c: Vec<i32>)
    ensures
        // Reconstructs the original exactly
        b@ + c@ == a@,
        // Lengths add up
        b@.len() + c@.len() == a@.len(),
        // If original length > 1, both parts are strictly shorter
        a@.len() > 1 ==> (b@.len() < a@.len() && c@.len() < a@.len()),
{
    let n = a.len();

    // Choose a split point.
    // - If n <= 1, we pick 0 so the "strictly shorter" condition is vacuously true.
    // - If n > 1, we pick n/2, which satisfies 0 < k < n.
    let k: usize = if n > 1 { n / 2 } else { 0 };

    // Build the two output vectors.
    let mut b_vec: Vec<i32> = Vec::new();
    let mut c_vec: Vec<i32> = Vec::new();

    let mut i: usize = 0;

    while i < k
        invariant
            i <= k,
            k <= n,
            b_vec@ == a@.subrange(0, i as int),
            c_vec@ == Seq::<i32>::empty(),
    {
        b_vec.push(a[i]);
        i += 1;
    }

    while i < n
        invariant
            k <= i,
            i <= n,
            b_vec@ == a@.subrange(0, k as int),
            c_vec@ == a@.subrange(k as int, i as int),
    {
        c_vec.push(a[i]);
        i += 1;
    }

    // Helpful fact for Verus: when n > 1, k = n/2 is in (0, n).
    // This establishes both outputs are strictly shorter than the original.
    if n > 1 {
        assert(k > 0);
        assert(k < n);
        assert(b_vec.len() == k);
        assert(c_vec.len() == n - k);
    }

    (b_vec, c_vec)
}

} // verus!